/**
 * Sidebar for the "Agent Plans" docs instance, which serves `docs/plans/`.
 *
 * The sidebar is autogenerated from the folder, so a plan written by ce-brainstorm
 * or ce-plan appears on the site with no config change. Plan filenames start with
 * their timestamp, so the ordering is chronological.
 *
 * @type {import('@docusaurus/plugin-content-docs').SidebarsConfig}
 */
const sidebars = {
  plansSidebar: [{type: 'autogenerated', dirName: '.'}],
};

export default sidebars;
